import { subject, where } from '../xl/ttl.js'
import { Query } from '../query.js'

export class DELETE extends Query { DELETE = {}
  static one (...args) { return (new this)._set('one',true)._set('from', subject (...args)) }
  static from (...args) { return (new this)._set('from', subject (...args)) }
  where (...args) { return this._add('where', where (...args)) }
}
